import React, { useState, useRef } from "react";

const FOUINEUR_IMG = "data:image/jpeg;base64,";
const CASSEUR_IMG = "data:image/jpeg;base64,";
const PARRAIN_IMG = "data:image/jpeg;base64,";

/* ─────────────────────────────────────────────────────────────
   LE-RAT.FR — le match de la négo
   Kickoff staté (rat → marketplace → annonce) puis match mobile-first.
   Chaque coup suggéré est un "draft" ré-rollable par les 2 autres rats.
   La jauge est pilotée par l'analyse IA des réponses vendeur.
   État en mémoire, aucun stockage. API Claude + vision.
   ───────────────────────────────────────────────────────────── */

const OPERATORS = [
  {
    key: "fouineur", codename: "LE FOUINEUR", real: "Le Technique", poste: "TEC", ovr: 86, img: FOUINEUR_IMG,
    theme: { main: "#35C8C0", deep: "#10332f", glow: "rgba(53,200,192,.35)", ink: "#05201d" },
    tagline: "Il flaire le bon plan. Tout est sourcé.",
    stats: { ANC: 88, PRE: 55, REL: 60, SAG: 80 },
    persona: "Tu es LE FOUINEUR. Tu négocies par la DATA et les FAITS. Tu ancres bas mais tu justifies chaque euro avec des chiffres : cote du marché, annonces comparables, kilométrage, défauts connus et typiques du modèle, entretien à prévoir, contrôle technique. Froid, factuel, imparable — tout est sourcé, le vendeur ne peut pas contester.",
  },
  {
    key: "casseur", codename: "LE CASSEUR", real: "Le Closer", poste: "ATT", ovr: 85, img: CASSEUR_IMG,
    theme: { main: "#E5484D", deep: "#3a1416", glow: "rgba(229,72,77,.35)", ink: "#200708" },
    tagline: "Cash en main. Il casse le prix, pas le temps.",
    stats: { ANC: 78, PRE: 95, REL: 45, SAG: 62 },
    persona: "Tu es LE CASSEUR. Tu négocies par la PRESSION et l'urgence. Cash en main, disponible tout de suite : tu poses un budget max ferme comme un mur non négociable et tu offres la tranquillité (paiement immédiat, tu te déplaces) en échange du prix. Direct, cash, tu ne négocies pas des heures. Ferme mais jamais insultant.",
  },
  {
    key: "parrain", codename: "LE PARRAIN", real: "Le Patient", poste: "MIL", ovr: 87, img: PARRAIN_IMG,
    theme: { main: "#9B8BF5", deep: "#241f3d", glow: "rgba(155,139,245,.35)", ink: "#120f22" },
    tagline: "Il ne hausse jamais le ton.",
    stats: { ANC: 55, PRE: 40, REL: 92, SAG: 96 },
    persona: "Tu es LE PARRAIN. Tu négocies par la PSYCHOLOGIE et la patience. Tu ne poses AUCUNE offre chiffrée frontale dans ce message. Tu crées du lien, tu poses les bonnes questions, tu montres un intérêt réel mais mesuré, tu ne hausses jamais le ton. Objectif : que le vendeur baisse de lui-même ou reste ouvert à une baisse plus tard. Calme, fin, jamais insistant.",
  },
];
const OP = (k) => OPERATORS.find((o) => o.key === k);
const eur = (n) => (n || n === 0 ? Number(n).toLocaleString("fr-FR") + " €" : "—");
const MARKETS = { leboncoin: "Leboncoin", facebook: "Facebook Marketplace" };
const DEFAULT_ENDPOINT = "https://api.anthropic.com/v1/messages";
let API_ENDPOINT = DEFAULT_ENDPOINT;

/* ── Prompts ── */
function playSystem(op, m) {
  const hist = m.thread.map((t) => (t.side === "nous" ? `NOUS (${OP(t.opKey).codename})` : "VENDEUR") + " : " + t.text).join("\n");
  return `${op.persona}

CADRE — négociation d'achat d'occasion entre particuliers sur ${MARKETS[m.market] || "une marketplace"} (France).
Règles : français, ton de particulier, vouvoiement par défaut. Message court et humain (2-5 phrases), sans liste. N'invente pas de fait précis inconnu ; appuie-toi sur les défauts génériques connus du modèle. Ne propose jamais plus que le PRIX MAX. Reste fidèle à ton personnage.

CONTEXTE DU MATCH :
Annonce : ${m.annonce}
Prix affiché : ${eur(m.affiche)} · Objectif : ${eur(m.vise)} · Max absolu : ${eur(m.max)}
${hist ? "Historique :\n" + hist : "Aucun échange : c'est un PREMIER CONTACT."}

Produis NOTRE prochain message. Réponds UNIQUEMENT en JSON valide, sans balises :
{"message":"le message prêt à envoyer","note":"1 phrase : le coup tenté"}`;
}

function analyzeSystem(m, played) {
  const hist = m.thread.map((t) => (t.side === "nous" ? `NOUS (${OP(t.opKey).codename})` : "VENDEUR") + " : " + t.text).join("\n");
  const roster = played.map((k) => `${k} = ${OP(k).codename}`).join(", ");
  return `Tu es l'ARBITRE d'un match de négociation d'achat d'occasion. Tu évalues UNIQUEMENT le dernier message du VENDEUR (texte ou capture d'écran).

CONTEXTE :
Annonce : ${m.annonce}
Prix affiché : ${eur(m.affiche)} · Objectif : ${eur(m.vise)} · Max absolu : ${eur(m.max)}
Jauge actuelle : ${m.gauge}/100 · Négociateurs intervenus : ${roster || "aucun"}
${hist ? "Historique :\n" + hist : ""}

Ta mission :
1. Fixe la JAUGE (0-100) reflétant l'avancée vers un deal CONCLU au prix voulu (100 = accepté). Cohérente avec la jauge actuelle : monte si le vendeur se rapproche, baisse s'il se braque.
2. "prixVendeur" : prix auquel le vendeur est prêt maintenant (nombre €) ou null.
3. "statut" : "conclu" si accord clair (ex : "ok pour moi", "j'accepte votre offre", "rdv demain pour l'achat", "vendu", accord ferme ≤ max) ; "perdu" si refus catégorique / vendu ailleurs / coupe court ; sinon "en_cours".
4. Si conclu OU perdu : note chaque négociateur intervenu (0.0-10.0, une décimale), désigne "mvp" (clé de celui qui a le plus conclu, meilleure note), et une "recompense" (titre court stylé). Notes plus basses si deal perdu.

Réponds UNIQUEMENT en JSON valide, sans balises :
{"lecture":"1-2 phrases d'analyse","gauge":0-100,"prixVendeur":nombre ou null,"statut":"en_cours|conclu|perdu","mvp":"clé ou null","ratings":[{"opKey":"clé","note":0.0,"recompense":"titre"}]}
Si en_cours : mvp=null, ratings=[].`;
}

const EXTRACT_SYSTEM = `Tu extrais les infos d'une annonce d'occasion (texte ou capture d'écran). Réponds UNIQUEMENT en JSON valide sans balises :
{"annonce":"résumé court : objet, marque/modèle, état, année/km si véhicule","prixAffiche":nombre en euros ou null}`;

function extractJson(text) {
  let t = text.replace(/```json/gi, "").replace(/```/g, "").trim();
  const s = t.indexOf("{"), e = t.lastIndexOf("}");
  if (s !== -1 && e !== -1 && e > s) t = t.slice(s, e + 1);
  try { return JSON.parse(t); }
  catch (err) { throw new Error("réponse non-JSON du modèle : " + text.slice(0, 120)); }
}

async function callClaude(system, userContent) {
  const content = typeof userContent === "string"
    ? system + "\n\n" + userContent
    : [{ type: "text", text: system }, ...userContent];
  let res;
  try {
    res = await fetch(API_ENDPOINT, {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ model: "claude-sonnet-4-5", max_tokens: 1000, messages: [{ role: "user", content }] }),
    });
  } catch (e) {
    throw new Error("connexion à l'IA impossible (réseau/runtime) — " + e.message);
  }
  if (!res.ok) {
    let body = ""; try { body = await res.text(); } catch (e) {}
    throw new Error("API HTTP " + res.status + " — " + body.slice(0, 160));
  }
  const data = await res.json();
  if (data.error) throw new Error("API : " + (data.error.message || JSON.stringify(data.error)));
  const text = (data.content || []).filter((b) => b.type === "text").map((b) => b.text).join("\n");
  if (!text.trim()) throw new Error("réponse vide de l'IA");
  return extractJson(text);
}
const imgContent = (shot, text) => [{ type: "image", source: { type: "base64", media_type: shot.mediaType, data: shot.data } }, { type: "text", text }];

/* ── Avatar ── */
function Avatar({ type, theme, img, size = 96 }) {
  const skin = "#E8C9A8";
  if (img && !img.startsWith("__")) return (<div style={{ width: size, height: size, borderRadius: 14, backgroundImage: `url(${img})`, backgroundSize: "cover", backgroundPosition: "top center", border: `1px solid ${theme.main}` }} />);
  return (
    <svg width={size} height={size} viewBox="0 0 120 120" style={{ display: "block" }}>
      <rect width="120" height="120" rx="14" fill={theme.deep} />
      <path d="M18 120 C18 96 38 84 60 84 C82 84 102 96 102 120 Z" fill={theme.deep} stroke={theme.main} strokeWidth="2" />
      <rect x="52" y="66" width="16" height="16" fill={skin} /><circle cx="60" cy="52" r="22" fill={skin} />
    </svg>
  );
}

function Card({ op, selected, onSelect }) {
  const t = op.theme;
  return (
    <button className="op-card" onClick={() => onSelect(op.key)} style={{
      borderColor: selected ? t.main : "#242832",
      boxShadow: selected ? `0 0 0 1px ${t.main}, 0 12px 34px ${t.glow}` : "0 6px 20px rgba(0,0,0,.4)",
      transform: selected ? "translateY(-6px)" : "none",
      background: `linear-gradient(160deg, ${t.deep} 0%, #0b0c10 62%)`,
    }}>
      <div className="op-top">
        <div className="op-rating" style={{ color: t.main }}><span className="op-ovr">{op.ovr}</span><span className="op-pos">{op.poste}</span></div>
        {selected && <span className="op-check" style={{ background: t.main, color: t.ink }}>✓</span>}
      </div>
      <div className="op-portrait"><Avatar type={op.key} theme={t} img={op.img} /></div>
      <div className="op-name" style={{ color: t.main }}>{op.codename}</div>
      <div className="op-real">{op.real}</div>
      <div className="op-stats">
        {Object.entries(op.stats).map(([k, v]) => (
          <div className="op-stat" key={k}><span className="op-stat-k">{k}</span><span className="op-stat-bar"><i style={{ width: `${v}%`, background: t.main }} /></span><span className="op-stat-v">{v}</span></div>
        ))}
      </div>
    </button>
  );
}

/* ── Icônes marketplace ── */
function MarketBtn({ id, active, onClick }) {
  const bg = id === "leboncoin" ? "#EC5A13" : "#1877F2";
  return (
    <button className="mk-btn" onClick={() => onClick(id)} style={{ borderColor: active ? bg : "#242832", boxShadow: active ? `0 0 0 1px ${bg}, 0 8px 24px ${bg}44` : "none" }}>
      <span className="mk-ic" style={{ background: bg }}>
        {id === "leboncoin" ? (
          <svg viewBox="0 0 24 24" width="20" height="20"><path d="M4 4h8.5l7.5 7.5-8.5 8.5L4 12.5V4z" fill="#fff" /><circle cx="8" cy="8" r="1.7" fill="#EC5A13" /></svg>
        ) : (
          <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="#fff" strokeWidth="1.7"><path d="M4 9l1.6-4.2h12.8L20 9M4.4 9h15.2v10.2H4.4zM8 19.2v-5h4v5" /></svg>
        )}
      </span>
      <span className="mk-name">{MARKETS[id]}</span>
      {active && <span className="mk-check" style={{ color: bg }}>✓</span>}
    </button>
  );
}

/* ── Jauge ── */
const gaugeColor = (g) => (g >= 80 ? "#35D07F" : g >= 45 ? "#F0A63C" : "#E36F6F");
function Gauge({ value, delta }) {
  const c = gaugeColor(value);
  return (
    <div>
      <div className="hz-gauge-head"><span className="hz-gauge-label">AVANCEMENT DU DEAL</span>
        <span className="hz-gauge-pct" style={{ color: c }}>{Math.round(value)}%{delta > 0 && <em className="hz-delta">+{delta}</em>}</span></div>
      <div className="hz-gauge-track"><div className="hz-gauge-fill" style={{ width: `${value}%`, background: c, boxShadow: `0 0 14px ${c}` }} />
        {[25, 50, 75].map((t) => <span key={t} className="hz-gauge-tick" style={{ left: `${t}%` }} />)}</div>
    </div>
  );
}

function ThreadItem({ turn, open, onToggle }) {
  const isUs = turn.side === "nous";
  const op = isUs ? OP(turn.opKey) : null;
  const accent = isUs ? op.theme.main : "#7C828C";
  const preview = turn.text.length > 50 ? turn.text.slice(0, 50) + "…" : turn.text;
  return (
    <div className="hz-ti" style={{ borderColor: open ? accent : "#20242e" }}>
      <button className="hz-ti-head" onClick={onToggle}>
        <span className="hz-ti-side" style={{ color: accent }}>{isUs ? "▸ " + op.codename : "◂ VENDEUR"}</span>
        {!open && <span className="hz-ti-prev">{preview}</span>}
        <span className="hz-ti-chev">{open ? "▲" : "▼"}</span>
      </button>
      {open && <div className="hz-ti-body">{turn.text}{turn.gnote && <div className="hz-ti-note">{turn.gnote}</div>}</div>}
    </div>
  );
}

export default function App() {
  // setup
  const [endpoint, setEndpoint] = useState("");
  const [selStart, setSelStart] = useState(null);
  const [market, setMarket] = useState(null);
  const [annonce, setAnnonce] = useState("");
  const [affiche, setAffiche] = useState("");
  const [vise, setVise] = useState("");
  const [max, setMax] = useState("");
  const [setupShot, setSetupShot] = useState(null);
  // match
  const [match, setMatch] = useState(null);
  const [turn, setTurn] = useState("nous");     // "nous" (draft en cours) | "vendeur" | (fin via statut)
  const [draft, setDraft] = useState(null);      // { opKey, text, note }
  const [seller, setSeller] = useState("");
  const [shot, setShot] = useState(null);
  const [openId, setOpenId] = useState(null);
  const [delta, setDelta] = useState(0);
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [copied, setCopied] = useState(false);
  const setupFile = useRef(null);
  const sellerFile = useRef(null);

  const played = match ? [...new Set(match.thread.filter((t) => t.side === "nous").map((t) => t.opKey))] : [];
  const readFile = (f, set) => { if (!f) return; const r = new FileReader(); r.onload = () => set({ data: r.result.split(",")[1], mediaType: f.type, name: f.name }); r.onerror = () => setError("Image illisible."); r.readAsDataURL(f); };

  const extract = async (shotObj) => {
    setBusy("extract"); setError("");
    try {
      const r = await callClaude(EXTRACT_SYSTEM, imgContent(shotObj, "Extrais les infos de cette annonce."));
      if (r.annonce) setAnnonce(r.annonce);
      if (r.prixAffiche) setAffiche(String(r.prixAffiche));
    } catch (e) { setError("Extraction KO (" + e.message + ") — saisis à la main."); }
    finally { setBusy(""); }
  };

  const genDraft = async (opKey, ctx) => {
    setBusy("gen"); setError("");
    try {
      const r = await callClaude(playSystem(OP(opKey), ctx), `Génère notre message pour ${OP(opKey).codename}.`);
      setDraft({ opKey, text: r.message, note: r.note }); setCopied(false);
    } catch (e) { setError("Le rat a raté son coup — " + e.message); }
    finally { setBusy(""); }
  };

  const launch = async () => {
    if (!selStart) return setError("Choisis ton rat.");
    if (!market) return setError("Choisis le marketplace.");
    if (!annonce.trim()) return setError("Renseigne l'annonce (colle ou upload).");
    setError("");
    const m = { market, annonce, affiche: +affiche || null, vise: +vise || null, max: +max || null, gauge: 0, statut: "en_cours", thread: [], prixFinal: null, result: null };
    setMatch(m); setTurn("nous"); setOpenId(null);
    await genDraft(selStart, m);
  };

  const sendDraft = () => {
    if (!draft) return;
    navigator.clipboard.writeText(draft.text).catch(() => {});
    const t = { id: Date.now(), side: "nous", opKey: draft.opKey, text: draft.text, gnote: draft.note };
    setMatch((m) => ({ ...m, thread: [...m.thread, t] }));
    setOpenId(t.id); setDraft(null); setTurn("vendeur"); setCopied(true); setTimeout(() => setCopied(false), 1600);
  };

  const analyze = async () => {
    if (!seller.trim() && !shot) return setError("Colle ou importe la réponse du vendeur.");
    setError(""); setBusy("analyze");
    const sellerTurn = { id: Date.now(), side: "vendeur", text: seller.trim() || "[capture importée]" };
    const draftMatch = { ...match, thread: [...match.thread, sellerTurn] };
    const brief = `DERNIER MESSAGE DU VENDEUR :\n${seller.trim() || "(voir la capture jointe)"}`;
    try {
      const r = await callClaude(analyzeSystem(draftMatch, played), shot ? imgContent(shot, brief) : brief);
      const newGauge = r.statut === "conclu" ? 100 : Math.max(0, Math.min(100, r.gauge));
      const d = Math.max(0, Math.round(newGauge - match.gauge));
      setDelta(d); setTimeout(() => setDelta(0), 2200);
      const committed = { ...sellerTurn, gnote: r.lecture };
      const finished = r.statut !== "en_cours";
      const updated = { ...match, thread: [...match.thread, committed], gauge: newGauge, statut: r.statut, prixFinal: r.prixVendeur ?? match.prixFinal, result: finished ? { mvp: r.mvp, ratings: r.ratings || [] } : null };
      setMatch(updated); setOpenId(committed.id); setSeller(""); setShot(null); setBusy("");
      if (!finished) {
        const lastRat = [...updated.thread].reverse().find((t) => t.side === "nous")?.opKey || selStart;
        setTurn("nous"); await genDraft(lastRat, updated);
      }
    } catch (e) { setError("Analyse KO — " + e.message); setBusy(""); }
  };

  const reset = () => { setMatch(null); setDraft(null); setSelStart(null); setMarket(null); setAnnonce(""); setAffiche(""); setVise(""); setMax(""); setSetupShot(null); setSeller(""); setShot(null); setDelta(0); setTurn("nous"); setError(""); };

  /* ═══ KICKOFF ═══ */
  if (!match) {
    const step2 = !!selStart, step3 = step2 && !!market, ready = step3 && annonce.trim();
    return (
      <div className="hz-root"><style>{CSS}</style><div className="hz-scan" />
        <div className="hz-wrap">
          <header><div className="hz-kicker">LE-RAT.FR · LE MATCH DE LA NÉGO</div>
            <h1 className="hz-title">TON ÉQUIPE<br /><span>TA MISSION</span></h1></header>

          <div className="hz-ep">
            <span className="hz-ep-l">ENDPOINT IA · ton Worker Cloudflare</span>
            <input value={endpoint} onChange={(e) => { const v = e.target.value.trim(); setEndpoint(v); API_ENDPOINT = v || DEFAULT_ENDPOINT; }} placeholder="https://lerat-worker.xxx.workers.dev" />
            {!endpoint && <span className="hz-ep-warn">Sans Worker, l'appel direct échoue dans l'artifact.</span>}
          </div>

          <div className="step"><div className="step-n">1 · TON RAT</div>
            <div className="hz-roster">{OPERATORS.map((o) => <Card key={o.key} op={o} selected={selStart === o.key} onSelect={(k) => setSelStart(k)} />)}</div>
            {selStart && <div className="hz-picked" style={{ color: OP(selStart).theme.main }}>» {OP(selStart).codename} — {OP(selStart).tagline}</div>}
          </div>

          {step2 && (
            <div className="step reveal"><div className="step-n">2 · LE TERRAIN</div>
              <div className="mk-row"><MarketBtn id="leboncoin" active={market === "leboncoin"} onClick={setMarket} /><MarketBtn id="facebook" active={market === "facebook"} onClick={setMarket} /></div>
            </div>
          )}

          {step3 && (
            <div className="step reveal"><div className="step-n">3 · L'ANNONCE</div>
              <div className="hz-panel" style={{ marginTop: 0 }}>
                <label className="hz-f"><span>Colle le texte de l'annonce</span>
                  <textarea rows={4} value={annonce} onChange={(e) => setAnnonce(e.target.value)} placeholder="Scénic III 7 places diesel, 180 000 km, 2013…" /></label>
                <div className="hz-file">
                  <button className="hz-ghost" onClick={() => setupFile.current?.click()} disabled={busy === "extract"}>{busy === "extract" ? "Lecture…" : setupShot ? "📎 " + setupShot.name : "⚡ Upload rapide de l'annonce"}</button>
                  {setupShot && <button className="hz-ghost hz-del" onClick={() => setSetupShot(null)}>Retirer</button>}
                  <input ref={setupFile} type="file" accept="image/*" hidden onChange={(e) => { const f = e.target.files?.[0]; readFile(f, (s) => { setSetupShot(s); extract(s); }); }} />
                </div>
                <div className="hz-row3">
                  <label className="hz-f"><span>Affiché €</span><input inputMode="numeric" value={affiche} onChange={(e) => setAffiche(e.target.value)} placeholder="4000" /></label>
                  <label className="hz-f"><span>Visé €</span><input inputMode="numeric" value={vise} onChange={(e) => setVise(e.target.value)} placeholder="3000" /></label>
                  <label className="hz-f"><span>Max €</span><input inputMode="numeric" value={max} onChange={(e) => setMax(e.target.value)} placeholder="3400" /></label>
                </div>
              </div>
            </div>
          )}

          {error && <div className="hz-err">{error}</div>}
        </div>

        <div className="hz-dock">
          <button className="hz-cta" onClick={launch} disabled={!ready || busy === "gen"}
            style={{ background: ready ? OP(selStart).theme.main : "#2a2f3a", color: ready ? OP(selStart).theme.ink : "#6b7280", boxShadow: ready ? `0 8px 26px ${OP(selStart).theme.glow}` : "none" }}>
            {busy === "gen" ? "COUP D'ENVOI…" : ready ? "⚽ LANCER LE MATCH" : selStart ? (market ? "COMPLÈTE L'ANNONCE" : "CHOISIS LE TERRAIN") : "CHOISIS TON RAT"}
          </button>
        </div>
      </div>
    );
  }

  /* ═══ MATCH ═══ */
  const finished = match.statut !== "en_cours";
  const won = match.statut === "conclu";
  const ratings = (match.result?.ratings || []).slice().sort((a, b) => b.note - a.note);
  const others = draft ? OPERATORS.filter((o) => o.key !== draft.opKey) : [];

  return (
    <div className="hz-root"><style>{CSS}</style><div className="hz-scan" />
      <div className="hz-wrap">
        <div className="hz-hud">
          <div className="hz-hud-top"><span className="hz-mk" style={{ background: match.market === "leboncoin" ? "#EC5A13" : "#1877F2" }}>{MARKETS[match.market]}</span>
            <button className="hz-quit" onClick={reset}>Quitter</button></div>
          <Gauge value={match.gauge} delta={delta} />
          <div className="hz-kpis">
            <Kpi label="AFFICHÉ" val={eur(match.affiche)} />
            <Kpi label="VISÉ" val={eur(match.vise)} hi="#9B8BF5" />
            <Kpi label="MAX" val={eur(match.max)} hi="#E36F6F" />
            <Kpi label="VENDEUR" val={eur(match.prixFinal)} hi={gaugeColor(match.gauge)} />
          </div>
        </div>

        <div className="hz-annonce">{match.annonce}</div>

        {match.thread.length > 0 && (
          <div className="hz-thread">{match.thread.map((t) => <ThreadItem key={t.id} turn={t} open={openId === t.id} onToggle={() => setOpenId(openId === t.id ? null : t.id)} />)}</div>
        )}

        {/* Draft en cours */}
        {!finished && draft && (
          <div className="draft" style={{ borderColor: OP(draft.opKey).theme.main, boxShadow: `0 12px 34px ${OP(draft.opKey).theme.glow}` }}>
            <div className="draft-head"><div className="draft-mini"><Avatar type={draft.opKey} theme={OP(draft.opKey).theme} img={OP(draft.opKey).img} size={40} /></div>
              <div><div className="draft-name" style={{ color: OP(draft.opKey).theme.main }}>{OP(draft.opKey).codename}</div><div className="draft-note">{draft.note}</div></div></div>
            <p className="hz-msg">{draft.text}</p>
            <button className="hz-cta hz-cta-sm" onClick={sendDraft} style={{ background: OP(draft.opKey).theme.main, color: OP(draft.opKey).theme.ink }}>
              {copied ? "COPIÉ — envoie-le au vendeur" : "COPIER & ENVOYER"}
            </button>
            <div className="reroll"><span className="reroll-l">Pas convaincu ? Fais rejouer</span>
              <div className="reroll-btns">{others.map((o) => (
                <button key={o.key} className="reroll-chip" onClick={() => genDraft(o.key, match)} disabled={busy === "gen"}
                  style={{ borderColor: o.theme.main }}><Avatar type={o.key} theme={o.theme} img={o.img} size={34} /><span style={{ color: o.theme.main }}>{o.codename.replace("LE ", "")}</span></button>
              ))}</div>
            </div>
          </div>
        )}
        {!finished && busy === "gen" && !draft && <div className="hz-loading">Le rat prépare son coup…</div>}

        {/* Réponse vendeur */}
        {!finished && turn === "vendeur" && !draft && (
          <div className="hz-panel">
            <div className="hz-panel-title">RÉPONSE DU VENDEUR</div>
            <label className="hz-f"><span>Colle sa réponse</span>
              <textarea rows={3} value={seller} onChange={(e) => setSeller(e.target.value)} placeholder="« Je peux faire un petit geste… »" /></label>
            <div className="hz-file">
              <button className="hz-ghost" onClick={() => sellerFile.current?.click()}>{shot ? "📎 " + shot.name : "⚡ Screenshot"}</button>
              {shot && <button className="hz-ghost hz-del" onClick={() => setShot(null)}>Retirer</button>}
              <input ref={sellerFile} type="file" accept="image/*" hidden onChange={(e) => readFile(e.target.files?.[0], setShot)} />
            </div>
            <button className="hz-cta hz-cta-sm hz-analyze" onClick={analyze} disabled={busy === "analyze"}>{busy === "analyze" ? "ANALYSE VIDÉO…" : "ANALYSER LA RÉPONSE"}</button>
          </div>
        )}

        {error && <div className="hz-err">{error}</div>}

        {/* Fin */}
        {finished && (
          <div className={`hz-end ${won ? "win" : "lose"}`}>
            <div className="hz-end-banner">{won ? "DEAL REMPORTÉ" : "DEAL PERDU"}</div>
            <div className="hz-cross">
              <CrossRow label="Prix affiché" val={eur(match.affiche)} />
              <CrossRow label="Prix final" val={eur(match.prixFinal)} strong hi={won ? "#35D07F" : "#E36F6F"} />
              {won && match.affiche && match.prixFinal != null && <CrossRow label="Économie" val={"− " + eur(match.affiche - match.prixFinal)} hi="#35D07F" strong />}
              {match.vise != null && match.prixFinal != null && <CrossRow label="Vs objectif" val={match.prixFinal <= match.vise ? "Objectif atteint ✓" : "Dépassé de " + eur(match.prixFinal - match.vise)} hi={match.prixFinal <= match.vise ? "#35D07F" : "#F0A63C"} />}
              {match.max != null && match.prixFinal != null && <CrossRow label="Vs plafond" val={match.prixFinal <= match.max ? "Sous le max ✓" : "Plafond crevé ✗"} hi={match.prixFinal <= match.max ? "#35D07F" : "#E36F6F"} />}
            </div>
            <div className="hz-ratings-title">FEUILLE DE NOTES</div>
            <div className="hz-ratings">{ratings.map((r) => { const o = OP(r.opKey); if (!o) return null; const mvp = match.result?.mvp === r.opKey;
              return (<div key={r.opKey} className="hz-rating" style={{ borderColor: mvp ? o.theme.main : "#20242e" }}>
                <Avatar type={o.key} theme={o.theme} img={o.img} size={46} />
                <div className="hz-rating-mid"><div className="hz-rating-name" style={{ color: o.theme.main }}>{o.codename}{mvp && <span className="hz-mvp">★ MVP</span>}</div><div className="hz-rating-rec">{r.recompense}</div></div>
                <div className="hz-rating-note" style={{ color: o.theme.main }}>{r.note.toFixed(1)}</div></div>); })}</div>
            <button className="hz-cta" onClick={reset} style={{ background: "#E7E9EC", color: "#0b0c10" }}>NOUVELLE NÉGO</button>
          </div>
        )}
      </div>
    </div>
  );
}

function Kpi({ label, val, hi }) { return <div className="hz-kpi"><span className="hz-kpi-l">{label}</span><span className="hz-kpi-v" style={hi ? { color: hi } : null}>{val}</span></div>; }
function CrossRow({ label, val, hi, strong }) { return <div className="hz-cross-row"><span>{label}</span><span style={{ color: hi || "#E7E9EC", fontWeight: strong ? 700 : 500 }}>{val}</span></div>; }

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Anton&family=Oswald:wght@400;500;600;700&display=swap');
*{-webkit-tap-highlight-color:transparent;box-sizing:border-box;}
.hz-root{position:relative;min-height:100vh;background:radial-gradient(1200px 600px at 50% -10%, #171a24 0%, #0a0b0e 55%);color:#E7E9EC;font-family:'Oswald',system-ui,sans-serif;overflow-x:hidden;}
.hz-scan{position:fixed;inset:0;pointer-events:none;z-index:2;background:repeating-linear-gradient(180deg, rgba(255,255,255,.025) 0 1px, transparent 1px 3px);mix-blend-mode:overlay;}
.hz-wrap{position:relative;z-index:1;max-width:600px;margin:0 auto;padding:22px 14px 120px;}
.hz-kicker{font-size:11px;letter-spacing:3px;color:#7C828C;font-weight:600;}
.hz-title{font-family:'Anton','Arial Narrow',sans-serif;font-size:36px;line-height:.92;margin:8px 0 22px;letter-spacing:1px;text-transform:uppercase;transform:skewX(-4deg);}
.hz-title span{-webkit-text-stroke:1px #E7E9EC;color:transparent;}
.hz-ep{background:#12141b;border:1px solid #2a2f3a;border-radius:12px;padding:12px;margin-bottom:20px;}
.hz-ep-l{display:block;font-size:10px;letter-spacing:1px;color:#7C828C;margin-bottom:6px;}
.hz-ep input{width:100%;background:#0c0e13;border:1px solid #242a35;border-radius:9px;color:#E7E9EC;padding:10px 12px;font-size:14px;font-family:system-ui,sans-serif;outline:none;}
.hz-ep input:focus{border-color:#3a4250;}
.hz-ep-warn{display:block;font-size:11px;color:#E5a04d;margin-top:6px;}
.step{margin-bottom:22px;}
.step-n{font-family:'Anton',sans-serif;font-size:13px;letter-spacing:2px;color:#5f6672;margin-bottom:11px;}
.reveal{animation:slideIn .35s ease;}
@keyframes slideIn{from{opacity:0;transform:translateY(10px);}to{opacity:1;transform:none;}}
.hz-roster{display:flex;gap:12px;overflow-x:auto;padding:6px 2px 12px;scroll-snap-type:x mandatory;}
.op-card{scroll-snap-align:center;flex:0 0 auto;width:172px;border:1px solid;border-radius:16px;padding:13px 11px 15px;cursor:pointer;text-align:left;transition:transform .18s, box-shadow .18s;color:#E7E9EC;font-family:'Oswald',sans-serif;}
.op-top{display:flex;justify-content:space-between;align-items:flex-start;height:32px;}
.op-rating{display:flex;flex-direction:column;line-height:1;font-family:'Anton',sans-serif;}
.op-ovr{font-size:28px;}.op-pos{font-size:11px;letter-spacing:1px;opacity:.8;margin-top:2px;}
.op-check{width:22px;height:22px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;}
.op-portrait{display:flex;justify-content:center;margin:2px 0 8px;}
.op-name{font-family:'Anton',sans-serif;font-size:18px;text-align:center;}
.op-real{text-align:center;font-size:12px;color:#8A909A;margin-bottom:10px;}
.op-stats{display:grid;gap:6px;}
.op-stat{display:grid;grid-template-columns:32px 1fr 24px;align-items:center;gap:7px;font-size:12px;}
.op-stat-k{color:#8A909A;}.op-stat-bar{height:5px;background:#20242e;border-radius:3px;overflow:hidden;}
.op-stat-bar i{display:block;height:100%;border-radius:3px;}.op-stat-v{text-align:right;font-weight:600;font-family:'Anton',sans-serif;}
.hz-picked{font-size:13px;margin:4px 2px 0;font-weight:500;}
.mk-row{display:grid;grid-template-columns:1fr 1fr;gap:11px;}
.mk-btn{display:flex;flex-direction:column;align-items:center;gap:9px;background:#101219;border:1px solid;border-radius:15px;padding:18px 10px;cursor:pointer;position:relative;transition:box-shadow .18s;}
.mk-ic{width:44px;height:44px;border-radius:12px;display:flex;align-items:center;justify-content:center;}
.mk-name{font-size:13px;color:#C4C9D0;letter-spacing:.3px;text-align:center;}
.mk-check{position:absolute;top:8px;right:10px;font-weight:700;}
.hz-panel{background:#12141b;border:1px solid #222732;border-radius:14px;padding:15px;display:grid;gap:12px;margin-top:14px;}
.hz-panel-title{font-family:'Anton',sans-serif;font-size:13px;letter-spacing:2px;color:#5f6672;}
.hz-f>span{display:block;font-size:11px;letter-spacing:.4px;color:#7C828C;margin-bottom:5px;text-transform:uppercase;}
.hz-f textarea,.hz-f input{width:100%;background:#0c0e13;border:1px solid #242a35;border-radius:9px;color:#E7E9EC;padding:11px 12px;font-size:15px;font-family:system-ui,sans-serif;outline:none;}
.hz-f textarea{resize:vertical;line-height:1.5;}
.hz-f textarea:focus,.hz-f input:focus{border-color:#3a4250;}
.hz-row3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:9px;}
.hz-file{display:flex;gap:10px;flex-wrap:wrap;}
.hz-ghost{background:transparent;border:1px solid #2b313c;border-radius:8px;color:#B7BCC4;padding:10px 13px;font-size:13px;cursor:pointer;font-family:'Oswald',sans-serif;}
.hz-del{color:#E36F6F;border-color:#3a2626;}
.hz-cta{width:100%;border:none;border-radius:12px;padding:15px;font-family:'Anton',sans-serif;font-size:16px;letter-spacing:1.1px;cursor:pointer;text-transform:uppercase;transform:skewX(-3deg);transition:filter .15s;}
.hz-cta:disabled{cursor:default;}.hz-cta:not(:disabled):active{filter:brightness(1.14);}
.hz-cta-sm{font-size:14px;padding:13px;margin-top:12px;}
.hz-analyze{background:#E7E9EC;color:#0b0c10;}
.hz-dock{position:fixed;left:0;right:0;bottom:0;z-index:3;padding:12px 14px calc(12px + env(safe-area-inset-bottom));background:linear-gradient(180deg, transparent, #0a0b0e 30%);max-width:600px;margin:0 auto;}
.hz-err{margin-top:14px;background:#241618;border:1px solid #4a2529;color:#E9A0A0;border-radius:9px;padding:11px 13px;font-size:14px;font-family:system-ui,sans-serif;}
.hz-loading{margin-top:16px;text-align:center;color:#8A909A;font-size:14px;letter-spacing:.5px;padding:16px;}
/* HUD */
.hz-hud{position:sticky;top:0;z-index:4;background:#0e1017ee;backdrop-filter:blur(8px);border:1px solid #20242e;border-radius:16px;padding:13px 15px;margin-bottom:12px;}
.hz-hud-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:11px;}
.hz-mk{font-size:10px;letter-spacing:.5px;color:#fff;padding:3px 9px;border-radius:20px;font-weight:600;}
.hz-quit{background:transparent;border:none;color:#6b7280;font-size:12px;cursor:pointer;font-family:'Oswald',sans-serif;}
.hz-gauge-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:7px;}
.hz-gauge-label{font-size:10px;letter-spacing:2px;color:#7C828C;}
.hz-gauge-pct{font-family:'Anton',sans-serif;font-size:24px;}
.hz-delta{font-size:13px;margin-left:6px;color:#35D07F;font-style:normal;animation:pop 2.2s ease;}
@keyframes pop{0%{opacity:0;transform:translateY(6px);}18%{opacity:1;transform:none;}80%{opacity:1;}100%{opacity:0;}}
.hz-gauge-track{position:relative;height:11px;background:#1b1f28;border-radius:7px;overflow:hidden;}
.hz-gauge-fill{height:100%;border-radius:7px;transition:width .7s cubic-bezier(.2,.8,.2,1);}
.hz-gauge-tick{position:absolute;top:0;bottom:0;width:1px;background:#0a0b0e;opacity:.6;}
.hz-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:12px;}
.hz-kpi{background:#0c0e13;border:1px solid #1c2029;border-radius:9px;padding:7px 4px;text-align:center;}
.hz-kpi-l{display:block;font-size:9px;letter-spacing:.5px;color:#6b7280;}
.hz-kpi-v{display:block;font-family:'Anton',sans-serif;font-size:14px;margin-top:3px;}
.hz-annonce{font-size:13px;color:#9AA0A8;font-family:system-ui,sans-serif;line-height:1.5;background:#101219;border:1px solid #20242e;border-radius:10px;padding:10px 12px;margin-bottom:12px;}
.hz-thread{display:grid;gap:8px;margin-bottom:12px;}
.hz-ti{border:1px solid;border-radius:11px;background:#101219;overflow:hidden;transition:border-color .2s;}
.hz-ti-head{width:100%;display:flex;align-items:center;gap:8px;background:transparent;border:none;padding:11px 13px;cursor:pointer;text-align:left;}
.hz-ti-side{font-family:'Anton',sans-serif;font-size:12px;white-space:nowrap;}
.hz-ti-prev{flex:1;font-size:12.5px;color:#7C828C;font-family:system-ui,sans-serif;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.hz-ti-chev{color:#5f6672;font-size:10px;margin-left:auto;}
.hz-ti-body{padding:0 13px 13px;font-size:15px;line-height:1.6;color:#EDEFF2;font-family:system-ui,sans-serif;white-space:pre-wrap;}
.hz-ti-note{margin-top:9px;font-size:12.5px;color:#8A909A;border-left:2px solid #2b313c;padding-left:9px;}
/* Draft */
.draft{background:#101219;border:1px solid;border-radius:16px;padding:15px;margin-bottom:12px;}
.draft-head{display:flex;gap:11px;align-items:center;margin-bottom:4px;}
.draft-mini{border-radius:10px;overflow:hidden;flex:0 0 auto;}
.draft-name{font-family:'Anton',sans-serif;font-size:16px;}
.draft-note{font-size:12.5px;color:#8A909A;font-family:system-ui,sans-serif;margin-top:2px;}
.hz-msg{margin:12px 0;padding:14px;font-size:16px;line-height:1.62;white-space:pre-wrap;color:#EDEFF2;font-family:system-ui,sans-serif;background:#0c0e13;border-radius:10px;}
.reroll{margin-top:14px;border-top:1px solid #1c2029;padding-top:12px;}
.reroll-l{font-size:12px;color:#7C828C;letter-spacing:.3px;}
.reroll-btns{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:9px;}
.reroll-chip{display:flex;align-items:center;gap:8px;background:#0c0e13;border:1px solid;border-radius:11px;padding:8px 10px;cursor:pointer;font-family:'Anton',sans-serif;font-size:12px;letter-spacing:.5px;}
.reroll-chip:disabled{opacity:.5;}
/* End */
.hz-end{margin-top:8px;border-radius:18px;padding:18px;border:1px solid;}
.hz-end.win{border-color:#35D07F;background:linear-gradient(160deg, rgba(53,208,127,.12), #101219 60%);}
.hz-end.lose{border-color:#E36F6F;background:linear-gradient(160deg, rgba(227,111,111,.12), #101219 60%);}
.hz-end-banner{font-family:'Anton',sans-serif;font-size:28px;letter-spacing:1px;text-align:center;transform:skewX(-4deg);margin-bottom:16px;}
.hz-end.win .hz-end-banner{color:#35D07F;}.hz-end.lose .hz-end-banner{color:#E36F6F;}
.hz-cross{background:#0c0e13;border:1px solid #1c2029;border-radius:12px;padding:6px 14px;margin-bottom:18px;}
.hz-cross-row{display:flex;justify-content:space-between;align-items:center;padding:10px 0;font-size:14px;border-bottom:1px solid #181c24;font-family:system-ui,sans-serif;}
.hz-cross-row:last-child{border-bottom:none;}.hz-cross-row>span:first-child{color:#8A909A;}
.hz-ratings-title{font-family:'Anton',sans-serif;font-size:13px;letter-spacing:2px;color:#5f6672;margin-bottom:11px;}
.hz-ratings{display:grid;gap:9px;margin-bottom:16px;}
.hz-rating{display:flex;align-items:center;gap:12px;background:#0c0e13;border:1px solid;border-radius:12px;padding:10px 12px;}
.hz-rating-mid{flex:1;}
.hz-rating-name{font-family:'Anton',sans-serif;font-size:15px;display:flex;align-items:center;gap:8px;}
.hz-mvp{font-size:10px;background:#F0A63C;color:#1a1206;border-radius:4px;padding:2px 6px;letter-spacing:.5px;}
.hz-rating-rec{font-size:12.5px;color:#9AA0A8;font-family:system-ui,sans-serif;margin-top:2px;}
.hz-rating-note{font-family:'Anton',sans-serif;font-size:30px;line-height:1;}
@media (max-width:380px){ .hz-kpi-v{font-size:12px;} .op-card{width:164px;} }
`;
